function wpbp_security_006( string $nonce, string $action ): string {
    $result = wp_verify_nonce( $nonce, $action );
    if ( 1 === $result ) {
        return 'fresh';
    }
    if ( 2 === $result ) {
        return 'aging';
    }
    return 'invalid';
}

